import os,json,subprocess
from pathlib import Path
project=Path("/srv/projects/lowcost-europa")
pairs=[(Path("/var/lib/lowcost-europa"),project/"data"),(Path("/root/project-secrets/lowcost-europa"),project/"private")]
out={"project":"lowcost-europa","status":"BLOCKED","changed":False}
def services():
 names=("ssh","nginx","postgresql@16-main","lowcost-europa","fadego-staging","pink-iptv-backend","pm2-root")
 return {n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip() for n in names}
done=[]
try:
 if not project.is_dir() or project.is_symlink():raise RuntimeError("invalid_project_root")
 expected={}
 for src,dst in pairs:
  if not src.is_dir() or src.is_symlink() or dst.exists() or dst.is_symlink():raise RuntimeError("source_or_destination_invalid")
  a=src.stat()
  if a.st_dev!=project.stat().st_dev:raise RuntimeError("cross_device_move")
  expected[str(src)]=(a.st_dev,a.st_ino,a.st_uid,a.st_gid,a.st_mode&0o777)
 before=services()
 for src,dst in pairs:
  os.rename(src,dst)
  done.append((src,dst))
  os.symlink(str(dst),src)
  a=dst.stat()
  if (a.st_dev,a.st_ino,a.st_uid,a.st_gid,a.st_mode&0o777)!=expected[str(src)] or not src.is_symlink() or src.resolve(strict=True)!=dst:
   raise RuntimeError("post_move_identity_mismatch")
 if services()!=before:raise RuntimeError("service_state_changed")
 out.update(status="MOVED_VERIFIED",changed=True,canonical_data="data",canonical_private="private",aliases_preserved=True,original_ownership_and_modes_preserved=True,protected_services_unchanged=True)
except Exception as e:
 out["reason"]=str(e)[:140]
 for src,dst in reversed(done):
  try:
   if src.is_symlink() and src.resolve(strict=False)==dst:src.unlink()
   if dst.is_dir() and not src.exists() and not src.is_symlink():os.rename(dst,src)
  except Exception:out["rollback"]="INCOMPLETE"
print(json.dumps(out,sort_keys=True))
if out["status"]!="MOVED_VERIFIED":raise SystemExit(3)
